    public Set dynamicSteps(Common _common, boolean _getAllSteps = false)
    {
        Set								ret = super(_common);
        Set								prodDims = TFMHelper::fieldGroupToSet(tableNum(InventDim),tableFieldGroupStr(InventDim, ProductDimensions));
        SetEnumerator					sEnum = prodDims.getEnumerator();
        TFMInventDimSetup				inventDimSetup;
        SysDictTable					DT;
        SysDictField					sdf;
        int								add = 41;
        SysDictType						dictType;
        TFMRegistrationCollectorList	listCollector;
        str								labelForField;
        InventTable						inventTable;
        Common							common = _common;

        ret = new Set(Types::Class);
		if (common == null && _getAllSteps)
        {
            select firstonly inventTable;
            common = inventTable;
        }

        if (!common)
        {
            return ret;
        }
        DT = new SysDictTable(common.tableId);
		if (!DT.fieldName2Id(extendedTypeStr(ItemId)))
        {
            return ret;
        }

        inventDimSetup = TFMInventDimSetup::Construct(InventTable::find(common.(DT.fieldName2Id(extendedTypeStr(ItemId)))));

        while (sEnum.moveNext())
        {
            if (!EcoResProductDimGroupSetup::newItemId(inventDimSetup.parmInventTable().ItemId).getFieldSetup(fieldName2Id(tableNum(InventDim),sEnum.current())).isActive() && !_getAllSteps)
            {
                continue;
            }
            sdf = new SysDictField(tableNum(InventDim), fieldName2Id(tableNum(InventDim),sEnum.current()));
            add++;
            dictType = new SysDictType(sdf.typeId());
            labelForField = dictType.label();
            listCollector = TFMRegistrationCollectorList::ListStep(false,add, strlwr(sdf.name()) ,labelForField,labelForField,dictType.help(),TFMInventDimHelper::getProductDimensionValues(inventDimSetup.parminventTable().Product,sEnum.current()),false,'',';',TFMInventDimHelper::inventDimField2GS1(sdf.name()));

            ret.add(listCollector);
        }

        return ret;
    }
